-- Starting listings: POC Premier Lodge and its trips. Prices left at 0 show as "Ask for price" until Jason sets them.

insert into public.listings (area_id, bay_system_id, slug, kind, category, title, summary, description, price_cents, price_unit, max_guests, min_nights, duration_hours, start_times, amenities, species, address, meeting_point, published)
select (select id from public.areas where slug = 'port-oconnor'), (select id from public.bay_systems where slug = 'matagorda-bay'), 'poc-premier-lodge', 'stay', 'house', 'POC Premier Lodge', 'Group lodge near Kingfisher Beach with a bay-view balcony and covered outdoor bar. Sleeps up to 14.', 'A basecamp for fishing crews, families and groups, a short walk from Kingfisher Beach and the public pier. The vaulted living room and kitchen island give everyone room to gather, the balcony looks over the bay, and the covered outdoor bar is where the day''s catch gets talked about. Pair it with a guided trip and the logistics are handled.', 0, 'night', 14, 2, null, '{}'::text[], array['Full kitchen','Washer and dryer','Bay-view balcony','Covered outdoor bar','Golf carts on request','Near Kingfisher Beach','Fish-cleaning table']::text[], '{}'::text[], '110 East Monroe Ave., Port O''Connor, TX 77982', null, true;

