select (select id from public.areas where slug = 'port-oconnor'), (select id from public.bay_systems where slug = 'matagorda-bay'), 'inshore-bay-fishing', 'trip', 'fishing', 'Inshore Bay Fishing', 'Five hours on the bay for redfish, speckled trout, black drum and flounder. Great for first-timers and kids.', 'Light-tackle inshore trip on a 24 ft bay boat with GPS, live well and trolling motor. Your guide picks the bay, reef or shoreline that is fishing best that day. Rods, tackle and ice are included. Bring your own food and drinks (no glass).', 75000, 'trip', 4, 1, 5, array['6:30 AM','1:00 PM']::text[], array['Rods and tackle','Ice','Kid friendly']::text[], array['Redfish','Speckled trout','Black drum','Flounder']::text[], null, 'POC Premier Lodge dock', true;

