select (select id from public.areas where slug = 'port-oconnor'), (select id from public.bay_systems where slug = 'espiritu-santo-bay'), 'wade-fishing-the-flats', 'trip', 'fishing', 'Wade Fishing the Flats', 'Sight-cast to redfish on the grass flats and back lakes of Espiritu Santo Bay.', 'Run to the flats, step off the boat and wade for tailing redfish and trout with artificial lures. Best for anglers who want the hunt.', 0, 'trip', 3, 1, 6, array['6:00 AM']::text[], array['Rods and tackle','Wading gear tips']::text[], array['Redfish','Speckled trout']::text[], null, null, true;

