select (select id from public.areas where slug = 'port-oconnor'), (select id from public.bay_systems where slug = 'jetties-gulf'), 'jetty-and-drift-fishing', 'trip', 'fishing', 'Jetty and Drift Fishing', 'Fish the Matagorda ship channel jetties and drift the passes for bull reds and black drum.', 'Structure fishing on the jetties with bait or lures, then drifting the channel when the tide is moving.', 0, 'trip', 4, 1, 5, array['6:30 AM']::text[], '{}'::text[], array['Bull redfish','Black drum','Sheepshead']::text[], null, null, true;

